#!/usr/bin/env node
/**
 * Installs prepare-commit-msg so version + Version History update on every commit.
 * Safe to re-run (overwrites the local hook wrapper only).
 */
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(__dirname, "..");
const hookPath = path.join(root, ".git", "hooks", "prepare-commit-msg");

const wrapper = `#!/usr/bin/env node
// Auto-generated by scripts/install-git-hooks.mjs - do not edit by hand.
const { spawnSync } = require("child_process");
const path = require("path");

const script = path.join(__dirname, "../../scripts/prepare-commit-msg.mjs");
const result = spawnSync(process.execPath, [script, ...process.argv.slice(2)], {
  stdio: "inherit",
});
process.exit(result.status ?? 1);
`;

fs.mkdirSync(path.dirname(hookPath), { recursive: true });
fs.writeFileSync(hookPath, wrapper, { mode: 0o755 });
console.log(`✓ Installed git hook: ${path.relative(root, hookPath)}`);
